function setCors(res: any) {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type");
}
function ok(res: any, data: unknown, extra: Record<string, unknown> = {}) {
  setCors(res);
  res.setHeader("Cache-Control", "public, max-age=60, s-maxage=300");
  res.status(200).json({ ok: true, data, ...extra });
}
function fail(res: any, status: number, message: string) {
  setCors(res);
  res.status(status).json({ ok: false, error: { status, message } });
}
function qs(req: any, key: string): string | undefined {
  const v = req.query[key];
  return Array.isArray(v) ? v[0] : v;
}
function num(req: any, key: string, def: number): number {
  const v = Number(qs(req, key));
  return Number.isFinite(v) && v > 0 ? v : def;
}


// ============================================================
// ENTRY POINT — SATU serverless function untuk SEMUA endpoint /api/*
// (menghemat kuota 12 functions di Vercel Hobby).
// Routing dilakukan berdasarkan path pada req.url.
// ============================================================




type Handler = (req: VercelRequest) => any;

function paginate(list: any[], req: VercelRequest) {
  const page = num(req, "page", 1);
  const limit = Math.min(num(req, "limit", 50), 500); // cap 500
  const total = list.length;
  const pages = Math.ceil(total / limit) || 1;
  const start = (page - 1) * limit;
  return { data: list.slice(start, start + limit), meta: { page, limit, total, pages } };
}

function filterText(list: any[], q: string | undefined, fields: string[]) {
  if (!q) return list;
  const needle = q.toLowerCase();
  return list.filter((it) => fields.some((f) => String(it[f] ?? "").toLowerCase().includes(needle)));
}

// Levenshtein distance untuk autocorrect
function levenshtein(a: string, b: string): number {
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  const dp: number[] = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    let prev = dp[0];
    dp[0] = i;
    for (let j = 1; j <= n; j++) {
      const tmp = dp[j];
      dp[j] = Math.min(dp[j] + 1, dp[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return dp[n];
}

// ---------------- HANDLERS ----------------
const H: Record<string, Handler> = {
  // GET /api
  index: () => {
    const m = KAMUS.meta || {};
    return {
      name: m.title, description: m.description, version: m.version, counts: m.counts || {},
      endpoints: [
        "/api", "/api/meta", "/api/entries", "/api/search", "/api/turunan", "/api/thematic",
        "/api/proverbs", "/api/cangkriman", "/api/dialogs", "/api/geguritan", "/api/sentences",
        "/api/saku", "/api/reverse", "/api/tanya-jawab", "/api/extra", "/api/latihan",
        "/api/rencana", "/api/unggah-ungguh", "/api/translate", "/api/suggest", "/api/status", "/api/openapi",
      ],
    };
  },

  // GET /api/meta
  meta: () => KAMUS.meta,

  // GET /api/entries
  entries: (req) => {
    const letter = qs(req, "letter");
    const q = qs(req, "q");
    const level = qs(req, "level");
    let list = KAMUS.entries;
    if (letter) list = list.filter((e: any) => e.letter.toLowerCase() === letter.toLowerCase());
    if (level) list = list.filter((e: any) => e.level === level);
    if (q) list = filterText(list, q, ["word", "meaning", "krama", "krama_inggil"]);
    const letters = [...new Set(KAMUS.entries.map((e: any) => e.letter))].sort();
    const levels = [...new Set(KAMUS.entries.map((e: any) => e.level))].sort();
    if (qs(req, "all") === "1") {
      return { data: list, meta: { page: 1, limit: list.length, total: list.length, pages: 1 }, letters, levels };
    }
    const p = paginate(list, req);
    return {
      data: p.data,
      meta: { ...p.meta, filters: { letter: letter || null, q: q || null, level: level || null } },
      letters,
      levels,
    };
  },

  // GET /api/search
  search: (req) => {
    const q = qs(req, "q") || "";
    const level = qs(req, "level");
    let list = filterText(KAMUS.entries, q, ["word", "meaning", "krama", "krama_inggil"]);
    if (level) list = list.filter((e: any) => e.level === level);
    return { query: q.toLowerCase().trim(), ...paginate(list, req) };
  },

  // GET /api/turunan
  turunan: (req) => {
    const list = filterText(KAMUS.turunan, qs(req, "q"), ["word", "meaning"]);
    return paginate(list, req);
  },

  // GET /api/thematic
  thematic: (req) => {
    const slug = qs(req, "slug");
    let list = KAMUS.thematic || [];
    if (slug) {
      const s = slug.toLowerCase();
      list = list.filter((t: any) => (t.slug || "").toLowerCase().includes(s) || t.title.toLowerCase().includes(s));
    }
    return { data: list, total: list.length };
  },

  // GET /api/proverbs
  proverbs: (req) => {
    const type = qs(req, "type");
    const q = qs(req, "q");
    const p = KAMUS.proverbs || {};
    if (type) {
      const map: Record<string, string> = {
        paribasan: "paribasan", bebasan: "bebasan", saloka: "saloka",
        entar: "tembung_entar", tembung_entar: "tembung_entar",
        pepatah: "pepatah", pitutur: "pitutur_luhur", pitutur_luhur: "pitutur_luhur",
      };
      const key = map[type.toLowerCase()];
      if (!key) throw new ApiError(400, "type tidak dikenal. Pilihan: paribasan, bebasan, saloka, tembung_entar, pepatah, pitutur_luhur");
      const rows = filterText(p[key] || [], q, ["jv", "id"]);
      return { type: key, data: rows, total: rows.length };
    }
    return { data: p, types: Object.keys(p) };
  },

  // GET /api/cangkriman
  cangkriman: (req) => {
    const list = filterText(KAMUS.cangkriman, qs(req, "q"), ["question", "answer"]);
    return { data: list, total: list.length };
  },

  // GET /api/dialogs
  dialogs: (req) => {
    const list = filterText(KAMUS.dialogs, qs(req, "q"), ["title"]);
    return { data: list, total: list.length };
  },

  // GET /api/geguritan
  geguritan: (req) => {
    const list = filterText(KAMUS.geguritan, qs(req, "q"), ["title", "jv"]);
    return { data: list, total: list.length };
  },

  // GET /api/sentences
  sentences: (req) => paginate(KAMUS.sentences_3levels, req),

  // GET /api/saku
  saku: (req) => paginate(filterText(KAMUS.kamus_saku, qs(req, "q"), ["ngoko", "krama", "id"]), req),

  // GET /api/reverse
  reverse: (req) => {
    const q = qs(req, "q") || "";
    const rows = (KAMUS.reverse || []).map((r: any) => ({ indonesia: r.id, ngoko: r.ngoko, krama: r.krama }));
    const list = filterText(rows, q, ["indonesia", "ngoko", "krama"]);
    return { query: q.toLowerCase().trim(), data: list, total: list.length };
  },

  // GET /api/tanya-jawab
  "tanya-jawab": () => ({ data: KAMUS.tanya_jawab || [], total: (KAMUS.tanya_jawab || []).length }),

  // GET /api/extra
  extra: () => ({ data: KAMUS.extra_lists || {}, categories: Object.keys(KAMUS.extra_lists || {}) }),

  // GET /api/latihan
  latihan: () => ({ data: KAMUS.latihan_soal || {}, total_soal: (KAMUS.latihan_soal?.soal || []).length }),

  // GET /api/rencana
  rencana: () => {
    const data = KAMUS.rencana_belajar || {};
    const total = Object.values(data).reduce((a: number, arr: any) => a + (arr?.length || 0), 0);
    return { data, total_hari: total };
  },

  // GET /api/unggah-ungguh
  "unggah-ungguh": () => ({ data: KAMUS.unggah_ungguh || {} }),

  // GET /api/parikan, /api/saroja, /api/macapat, /api/tembang-dolanan, /api/pelafalan
  parikan: () => ({ data: KAMUS.parikan || [] }),
  saroja: () => ({ data: KAMUS.saroja || [] }),
  macapat: () => ({ data: KAMUS.macapat || [] }),
  "tembang-dolanan": () => ({ data: KAMUS.tembang_dolanan || [] }),
  pelafalan: () => ({ data: KAMUS.pelafalan || [] }),

  // GET /api/translate?q=&dir=jv-id|id-jv
  translate: (req) => {
    const q = (qs(req, "q") || "").trim();
    const dir = (qs(req, "dir") || "jv-id").toLowerCase();
    const limit = Math.min(Math.max(num(req, "limit", 10), 1), 50);
    if (!q) return { data: [], total: 0, direction: dir, query: q };
    const needle = q.toLowerCase();
    if (dir === "id-jv") {
      // Indonesia → Jawa: gabung kamus balik + pencarian arti entri
      const rows = (KAMUS.reverse || []).map((r: any) => ({ indonesia: r.id, ngoko: r.ngoko, krama: r.krama }));
      const fromReverse = rows.filter((r: any) =>
        [r.indonesia, r.ngoko, r.krama].some((v) => String(v).toLowerCase().includes(needle))
      );
      const fromEntries = KAMUS.entries
        .filter((e: any) => e.meaning && String(e.meaning).toLowerCase().includes(needle))
        .map((e: any) => ({ indonesia: e.meaning, ngoko: e.word, krama: e.krama || null }));
      const merged: any[] = [];
      const seen = new Set<string>();
      for (const it of [...fromReverse, ...fromEntries]) {
        if (it.ngoko && !seen.has(it.ngoko)) {
          seen.add(it.ngoko);
          merged.push(it);
        }
      }
      const exact = merged.filter((m) => m.indonesia.toLowerCase() === needle);
      const prefix = merged.filter((m) => m.indonesia.toLowerCase() !== needle && m.indonesia.toLowerCase().startsWith(needle));
      const rest = merged.filter((m) => !exact.includes(m) && !prefix.includes(m));
      const list = [...exact, ...prefix, ...rest].slice(0, limit);
      return { data: list, total: list.length, direction: dir, query: q };
    }
    // Jawa → Indonesia (kamus inti)
    const list = KAMUS.entries.filter((e: any) =>
      [e.word, e.meaning, e.krama, e.krama_inggil].some((v) => v && String(v).toLowerCase().includes(needle))
    ).slice(0, limit).map((e: any) => ({
      jawa: e.word, indonesia: e.meaning, level: e.level,
      krama: e.krama || null, krama_inggil: e.krama_inggil || null,
      example: e.example || null,
    }));
    return { data: list, total: list.length, direction: dir, query: q };
  },

  // GET /api/suggest?q=&dir=jv-id|id-jv&limit= — autocorrect "mungkin kamu mencari"
  suggest: (req) => {
    const q = (qs(req, "q") || "").trim().toLowerCase();
    const dir = (qs(req, "dir") || "jv-id").toLowerCase();
    const limit = Math.min(Math.max(num(req, "limit", 5), 1), 10);
    if (!q) return { data: [], total: 0, query: q, direction: dir };
    const words = new Set<string>();
    if (dir === "id-jv") {
      for (const r of (KAMUS.reverse || [])) if (r.id) words.add(String(r.id));
      for (const e of KAMUS.entries) if (e.meaning && String(e.meaning).length <= 26) words.add(String(e.meaning));
    } else {
      for (const e of KAMUS.entries) {
        words.add(e.word);
        if (e.krama) words.add(e.krama);
        if (e.krama_inggil) words.add(e.krama_inggil);
      }
      for (const r of (KAMUS.reverse || [])) { words.add(r.ngoko); words.add(r.krama); }
    }
    const maxDist = Math.max(1, Math.min(3, Math.floor(q.length / 3)));
    const scored: { w: string; d: number }[] = [];
    for (const w of words) {
      const lw = w.toLowerCase();
      if (lw === q) continue;
      const d = levenshtein(q, lw);
      if (d <= maxDist) scored.push({ w, d });
    }
    scored.sort((a, b) => a.d - b.d || a.w.localeCompare(b.w));
    const data = scored.slice(0, limit).map((s) => s.w);
    return { data, total: data.length, query: q, direction: dir };
  },

  // GET /api/status — health check server (snapshot)
  status: () => {
    const t0 = Date.now();
    const entries = KAMUS.entries || [];
    const sample = entries.find((e: any) => e.word === "mangan");
    const mk = (name: string, ok: boolean, detail: string, message?: string) =>
      ({ name, ok, detail, message: ok ? undefined : (message || detail) });
    const checks = [
      mk("entries", entries.length > 0, entries.length + " entri", "Data entri kosong — kamus belum dimuat"),
      mk("search", !!sample, sample ? "sample 'mangan' OK" : "entri 'mangan' tidak ditemukan", "Entri uji 'mangan' tidak ada di data"),
      mk("turunan", (KAMUS.turunan || []).length > 0, (KAMUS.turunan || []).length + " kata", "Data kata turunan kosong"),
      mk("proverbs", ((KAMUS.proverbs || {}).paribasan || []).length > 0, ((KAMUS.proverbs || {}).paribasan || []).length + " paribasan", "Data paribasan kosong"),
      mk("translate", (KAMUS.reverse || []).length > 0, (KAMUS.reverse || []).length + " kata balik", "Data kamus balik kosong"),
      mk("thematic", (KAMUS.thematic || []).length > 0, (KAMUS.thematic || []).length + " tabel", "Data tematik kosong"),
    ];
    const latencyMs = Date.now() - t0;
    const failed = checks.filter((c) => !c.ok);
    const allOk = failed.length === 0;
    const status = allOk ? "operational" : "degraded";
    return {
      data: {
        status,
        message: allOk ? "Semua layanan berjalan normal" : (failed.length + " pemeriksaan gagal"),
        serverTime: new Date().toISOString(),
        version: KAMUS.meta?.version || "2.0.0",
        region: process.env.VERCEL_REGION || "unknown",
        runtime: "vercel-serverless",
        latencyMs,
        counts: KAMUS.meta?.counts || {},
        checks,
        issues: failed.map((c) => ({ check: c.name, message: c.message, detail: c.detail })),
      },
    };
  },

  // GET /api/openapi
  openapi: () => {
    const paths: Record<string, any> = {};
    for (const ep of Object.keys(H).filter((k) => !["index", "meta", "openapi"].includes(k))) {
      const p = "/api/" + ep.replace(/-/g, "-");
      paths[p] = { get: { summary: "Endpoint " + p, responses: { "200": { description: "OK" } } } };
    }
    return {
      openapi: "3.0.3",
      info: { title: "Kamus Jawa API", description: "Kamus Lengkap Basa Jawa (Ngoko, Krama, Krama Inggil) — REST API dinamis.", version: KAMUS.meta?.version || "1.0.0" },
      servers: [{ url: "/" }],
      paths,
    };
  },
};

class ApiError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

export default async function handler(req: VercelRequest, res: VercelResponse) {
  setCors(res);
  if (req.method === "OPTIONS") return res.status(204).end();
  if (req.method !== "GET") return fail(res, 405, "Method Not Allowed (gunakan GET)");

  try {
    // Path asli: biasanya /api/xxx. Fallback __path bila routing menghilangkan subpath.
    let pathname = "";
    try {
      pathname = new URL(req.url || "/", "http://x").pathname;
    } catch {
      pathname = "/";
    }
    if (pathname === "/api/entry" || pathname === "/api") {
      const fb = qs(req, "__path") || "";
      if (fb) pathname = "/api/" + fb.replace(/^\//, "");
    }
    let key = pathname.replace(/^\/api\/?/, "").replace(/\/$/, "") || "index";
    if (key === "entry") key = "index";
    const h = H[key];
    if (!h) return fail(res, 404, "Endpoint tidak ditemukan: /api/" + key);
    const payload = h(req);
    // Normalisasi: jika handler mengembalikan { data, ...extra } pakai itu;
    // jika mengembalikan objek lain, jadikan seluruhnya sebagai `data`.
    let data: unknown;
    let extra: Record<string, unknown> = {};
    if (payload && typeof payload === "object" && !Array.isArray(payload) && "data" in payload) {
      const { data: d, ...e } = payload as any;
      data = d;
      extra = e;
    } else {
      data = payload;
    }
    return ok(res, data, extra);
  } catch (err: any) {
    if (err instanceof ApiError) return fail(res, err.status, err.message);
    return fail(res, 500, "Terjadi kesalahan server: " + (err?.message || err));
  }
}
